// Get GitHub token resolved by Set node expression
const resolvedToken = $('Resolve Token').first().json.githubToken;

// Extract push payload from webhook
const webhookData = $('GitHub Push Webhook').first().json;
const payload = webhookData.body ?? webhookData;

const ref = payload.ref ?? '';
const branch = ref.replace('refs/heads/', '');

// Only process pushes to main
if (branch !== 'main') {
  return [];
}

const repo = payload.repository?.full_name ?? 'unknown/repo';
const before = payload.before ?? '';
const after = payload.after ?? '';

const commits = payload.commits ?? [];
if (commits.length === 0) {
  return [];
}

// Skip chore-only pushes
const hasNonChore = commits.some(c => {
  const msg = (c.message || '').toLowerCase();
  return !msg.startsWith('chore:') && !msg.startsWith('chore(') &&
         !msg.startsWith('docs:') && !msg.startsWith('docs(') &&
         !msg.startsWith('ci:') && !msg.startsWith('ci(');
});
if (!hasNonChore) {
  return [];
}

const commitMessages = commits.map(c => (c.message || '').split('\n')[0]);

// Fetch compare diff from GitHub API
const compareUrl = `https://api.github.com/repos/${repo}/compare/${before.substring(0,12)}...${after.substring(0,12)}`;
const compareRes = await this.helpers.httpRequest({
  method: 'GET',
  url: compareUrl,
  headers: {
    'Authorization': `Bearer ${resolvedToken}`,
    'Accept': 'application/vnd.github.v3+json'
  },
  json: true,
  timeout: 15000
});

const changedFiles = (compareRes.files || []).map(f => ({
  path: f.filename,
  diff: f.patch || '',
  status: f.status === 'added' ? 'added' : f.status === 'removed' ? 'removed' : 'modified'
}));

if (changedFiles.length === 0) {
  return [];
}

// Fetch content pages (.astro files in src/pages/)
const treeUrl = `https://api.github.com/repos/${repo}/git/trees/${after}?recursive=1`;
const treeRes = await this.helpers.httpRequest({
  method: 'GET',
  url: treeUrl,
  headers: {
    'Authorization': `Bearer ${resolvedToken}`,
    'Accept': 'application/vnd.github.v3+json'
  },
  json: true,
  timeout: 15000
});

const pageFiles = (treeRes.tree || [])
  .filter(f => f.type === 'blob' && f.path.startsWith('src/pages/') && f.path.endsWith('.astro'))
  .slice(0, 20);

const contentPages = [];
for (const pf of pageFiles) {
  try {
    const contentUrl = `https://api.github.com/repos/${repo}/contents/${pf.path}?ref=${after}`;
    const contentRes = await this.helpers.httpRequest({
      method: 'GET',
      url: contentUrl,
      headers: {
        'Authorization': `Bearer ${resolvedToken}`,
        'Accept': 'application/vnd.github.v3+json'
      },
      json: true,
      timeout: 10000
    });
    const decoded = Buffer.from(contentRes.content, 'base64').toString('utf-8');
    contentPages.push({ path: pf.path, content: decoded });
  } catch (e) {
    // Skip files we can't read
  }
}

if (contentPages.length === 0) {
  return [];
}

// Call the docs-sync agent
const agentResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://fyrk-agent-runtime.fly.dev/run/docs-sync',
  headers: { 'Content-Type': 'application/json' },
  body: {
    version: '0.1',
    input: {
      repo,
      ref,
      beforeSha: before,
      afterSha: after,
      changedFiles,
      contentPages,
      commitMessages
    },
    dryRun: false,
    publish: true
  },
  json: true,
  timeout: 60000
});

return [{ json: agentResponse }];

const resolvedToken = $('Resolve Token').first().json.githubToken;

const data = $input.first().json;
const output = data.output;
const suggestedUpdates = output.suggestedUpdates;

// Generate branch name
const date = new Date().toISOString().split('T')[0];
const shortId = data.runId ? data.runId.substring(0, 8) : Math.random().toString(36).substring(2, 10);
const branchName = `docs-sync/${date}-${shortId}`;

const repo = 'carlfrankalbert/nettside_fyrk';
const headers = {
  'Authorization': `Bearer ${resolvedToken}`,
  'Accept': 'application/vnd.github.v3+json',
  'Content-Type': 'application/json'
};

// Get default branch SHA
const mainRef = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.github.com/repos/${repo}/git/ref/heads/main`,
  headers,
  json: true,
  timeout: 10000
});
const baseSha = mainRef.object.sha;

// Create branch
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.github.com/repos/${repo}/git/refs`,
  headers,
  body: {
    ref: `refs/heads/${branchName}`,
    sha: baseSha
  },
  json: true,
  timeout: 10000
});

// Commit each updated file
for (const update of suggestedUpdates) {
  const existingFile = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${repo}/contents/${update.path}?ref=${branchName}`,
    headers,
    json: true,
    timeout: 10000
  });

  const encoded = Buffer.from(update.updatedContent).toString('base64');
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${repo}/contents/${update.path}`,
    headers,
    body: {
      message: `docs: oppdater ${update.path.split('/').pop()}`,
      content: encoded,
      sha: existingFile.sha,
      branch: branchName,
      committer: {
        name: 'FYRK Agent',
        email: 'agent@fyrk.no'
      }
    },
    json: true,
    timeout: 15000
  });
}

// Create PR
const prBody = output.prBody + '\n\n---\n🤖 Generated by FYRK docs-sync agent';
const pr = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.github.com/repos/${repo}/pulls`,
  headers,
  body: {
    title: output.prTitle,
    body: prBody,
    head: branchName,
    base: 'main'
  },
  json: true,
  timeout: 15000
});

return [{
  json: {
    repo,
    branchName,
    prTitle: output.prTitle,
    prUrl: pr.html_url,
    prNumber: pr.number
  }
}];
